import type { ClientBrief, Kol } from "../lib/types"
import payload from "../../functions/api/shortlist.json"

// ── DEMO FIXTURES = the committed pipeline output ───────────────────────────
// The bundled fallback IS the exact payload the Pages Function serves at
// /api/shortlist (generated by backend/app/pipeline.py in seed fixtures mode —
// regen command in functions/api/shortlist.ts). One source of truth: the
// fallback, the hosted API, and every on-screen number cannot drift apart.
// Handles are fictional on purpose: we never label a real creator "fake" in a
// public repo. Real (blurred) profiles appear only in the recorded live run.

const data = payload as unknown as {
  brief: ClientBrief
  kols: Kol[]
  screened: number
  recommended: number
  flagged: number
  cost: { usd: number; seconds: number; cacheHitRate: number }
}

export const client: ClientBrief = data.brief
export const kols: Kol[] = data.kols
export const cost = data.cost

export const summary = {
  screened: data.screened,
  recommended: data.recommended,
  flagged: data.flagged,
}

